const d = $input.first().json;
const h = d.health || {};
const redes = d.redes || [];
const erros = d.erros_recentes || [];
const ultimos = d.ultimos_videos || [];

// Escapa qualquer texto vindo do banco antes de injetar no HTML:
// nomes de arquivo e mensagens de erro sao dados externos.
const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const n = (v) => Number(v ?? 0);

const temAlerta = n(h.com_erro) > 0 || n(h.travados) > 0;

const card = (rotulo, valor, cor) => `
  <div class="card">
    <div class="valor" style="color:${cor}">${n(valor)}</div>
    <div class="rotulo">${rotulo}</div>
  </div>`;

const linhasRedes = redes.length
  ? redes.map((r) => `<tr>
      <td>${esc(r.rede_nome)}</td>
      <td>${r.enabled ? '<span class="on">ativa</span>' : '<span class="off">inativa</span>'}</td>
      <td>${n(r.publicados)}</td>
      <td>${n(r.erros)}</td>
      <td>${n(r.pendentes)}</td>
    </tr>`).join('')
  : '<tr><td colspan="5" class="vazio">nenhuma rede cadastrada</td></tr>';

const linhasErros = erros.length
  ? erros.map((e) => `<tr>
      <td>${esc(new Date(e.created_at).toLocaleString('pt-BR'))}</td>
      <td>${esc(e.workflow)}</td>
      <td>${esc(e.filename || '-')}</td>
      <td class="msg">${esc(e.message)}</td>
    </tr>`).join('')
  : '<tr><td colspan="4" class="vazio">nenhum erro registrado</td></tr>';

const linhasVideos = ultimos.length
  ? ultimos.map((v) => `<tr>
      <td>${n(v.id)}</td>
      <td>${esc(v.filename)}</td>
      <td><span class="badge b-${esc(v.status)}">${esc(v.status)}</span></td>
      <td>${esc(v.current_folder)}</td>
      <td>${esc(new Date(v.updated_at).toLocaleString('pt-BR'))}</td>
    </tr>`).join('')
  : '<tr><td colspan="5" class="vazio">nenhum vídeo no pipeline</td></tr>';

const html = `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="refresh" content="30">
<title>Project Atlas — Pipeline</title>
<style>
  :root { color-scheme: light dark; }
  * { box-sizing: border-box; }
  body { margin:0; padding:24px; font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;
         background:#0f1115; color:#e6e8ec; }
  h1 { font-size:20px; margin:0 0 4px; }
  .sub { color:#8b93a1; font-size:13px; margin-bottom:20px; }
  .status { display:inline-block; padding:4px 10px; border-radius:999px; font-size:12px; font-weight:600; }
  .ok { background:#10331f; color:#4ade80; }
  .alerta { background:#3a2410; color:#fbbf24; }
  .grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(120px,1fr)); gap:12px; margin-bottom:28px; }
  .card { background:#181b22; border:1px solid #252932; border-radius:10px; padding:14px; text-align:center; }
  .valor { font-size:26px; font-weight:700; }
  .rotulo { font-size:11px; color:#8b93a1; text-transform:uppercase; letter-spacing:.5px; margin-top:2px; }
  h2 { font-size:14px; text-transform:uppercase; letter-spacing:.5px; color:#8b93a1; margin:28px 0 10px; }
  .wrap { overflow-x:auto; background:#181b22; border:1px solid #252932; border-radius:10px; }
  table { width:100%; border-collapse:collapse; font-size:13px; min-width:520px; }
  th { text-align:left; padding:10px 12px; color:#8b93a1; font-weight:600; border-bottom:1px solid #252932; white-space:nowrap; }
  td { padding:10px 12px; border-bottom:1px solid #1e222a; }
  tr:last-child td { border-bottom:none; }
  .vazio { color:#5c636f; text-align:center; font-style:italic; }
  .msg { color:#f87171; max-width:420px; }
  .on { color:#4ade80; } .off { color:#5c636f; }
  .badge { padding:2px 8px; border-radius:6px; font-size:11px; font-weight:600; }
  .b-PENDING{background:#2a2f3a;color:#9ca3af} .b-TRANSCRIBING{background:#1e293b;color:#60a5fa}
  .b-TRANSCRIBED{background:#172554;color:#93c5fd} .b-PUBLISHING{background:#3a2410;color:#fbbf24}
  .b-PUBLISHED{background:#10331f;color:#4ade80} .b-PARTIAL{background:#3a2410;color:#fbbf24}
  .b-ERROR{background:#3f1d1d;color:#f87171}
  footer { margin-top:28px; color:#5c636f; font-size:12px; }
</style>
</head>
<body>
  <h1>Project Atlas — MofoMusic Pipeline</h1>
  <div class="sub">
    <span class="status ${temAlerta ? 'alerta' : 'ok'}">${temAlerta ? 'atenção necessária' : 'operacional'}</span>
    &nbsp;atualizado em ${esc(new Date().toLocaleString('pt-BR'))} · recarrega a cada 30s
  </div>

  <div class="grid">
    ${card('Total', h.total_videos, '#e6e8ec')}
    ${card('Pendentes', h.pendentes, '#9ca3af')}
    ${card('Transcrevendo', h.transcrevendo, '#60a5fa')}
    ${card('Transcritos', h.transcritos, '#93c5fd')}
    ${card('Publicando', h.publicando, '#fbbf24')}
    ${card('Publicados', h.publicados, '#4ade80')}
    ${card('Parciais', h.parciais, '#fbbf24')}
    ${card('Com erro', h.com_erro, '#f87171')}
    ${card('Travados', h.travados, '#f87171')}
    ${card('Erros 24h', h.erros_24h, '#f87171')}
  </div>

  <h2>Publicações por rede</h2>
  <div class="wrap"><table>
    <thead><tr><th>Rede</th><th>Estado</th><th>Publicados</th><th>Erros</th><th>Pendentes</th></tr></thead>
    <tbody>${linhasRedes}</tbody>
  </table></div>

  <h2>Últimos vídeos</h2>
  <div class="wrap"><table>
    <thead><tr><th>#</th><th>Arquivo</th><th>Status</th><th>Pasta</th><th>Atualizado</th></tr></thead>
    <tbody>${linhasVideos}</tbody>
  </table></div>

  <h2>Erros recentes</h2>
  <div class="wrap"><table>
    <thead><tr><th>Quando</th><th>Workflow</th><th>Arquivo</th><th>Mensagem</th></tr></thead>
    <tbody>${linhasErros}</tbody>
  </table></div>

  <footer>Project Atlas · dados lidos diretamente do PostgreSQL</footer>
</body>
</html>`;

return [{ json: { html } }];
